import { useState } from "react";

export function LinkEditor({
  linkText = "{{linkText}}",
  url = "{{url}}",
  openNewTab: initialOpenNewTab = {{openNewTab}},
  accent = "{{accent}}",
  variant = "{{variant}}",
}) {
  const [openNewTab, setOpenNewTab] = useState(initialOpenNewTab);
  const wrap = {
    popover: { borderRadius: 12, boxShadow: "0 12px 28px rgba(36,20,48,.18)", border: "1px solid #24143014" },
    inline: { borderTop: `3px solid ${accent}`, borderRadius: 0, boxShadow: "none" },
  }[variant] ?? {};
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", color: "#241430", background: "#FAF7F2", maxWidth: 300, padding: 18, ...wrap }}>
      <p style={{ margin: "0 0 10px", fontSize: 12, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".04em", color: accent }}>Edit link</p>
      <label style={{ display: "block", marginBottom: 10, fontSize: 13 }}>
        <span style={{ display: "block", marginBottom: 4, color: "#241430aa" }}>Text</span>
        <input type="text" defaultValue={linkText} aria-label="Link text" style={{ width: "100%", boxSizing: "border-box", padding: "8px 10px", border: "1.5px solid #24143026", borderRadius: 8, font: "inherit" }} />
      </label>
      <label style={{ display: "block", marginBottom: 10, fontSize: 13 }}>
        <span style={{ display: "block", marginBottom: 4, color: "#241430aa" }}>URL</span>
        <input type="url" defaultValue={url} aria-label="Link URL" style={{ width: "100%", boxSizing: "border-box", padding: "8px 10px", border: "1.5px solid #24143026", borderRadius: 8, font: "inherit" }} />
      </label>
      <label style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13, marginBottom: 12 }}>
        <input type="checkbox" checked={openNewTab} onChange={(e) => setOpenNewTab(e.target.checked)} />
        <span>Open in new tab</span>
      </label>
      <p style={{ margin: 0, fontSize: 13, borderTop: "1px solid #24143014", paddingTop: 10 }}>
        Preview: <a href={url} target={openNewTab ? "_blank" : undefined} rel={openNewTab ? "noopener" : undefined} style={{ color: accent, fontWeight: 600 }}>{linkText}</a>
      </p>
    </div>
  );
}
